// 1. Extract and sanitize incoming contact details
const webhookData = $('Webhook Trigger').item.json;
const body = webhookData.body || webhookData;

const rawName = (body.name || '').trim();
const rawEmail = (body.email || '').trim().toLowerCase();
const rawCompany = (body.company || '').trim();
const rawRole = (body.roleOrInterest || 'Full-time ServiceNow Architecture').trim();
const rawPhone = (body.phone || '').trim();
const rawMessage = (body.message || '').trim();
const rawSource = (body.source || 'geza-cv-website').trim();

if (!rawName) throw new Error('Name is required');
if (!rawEmail || !rawEmail.includes('@')) {
  throw new Error('Valid email address is required');
}
if (!rawMessage) throw new Error('Message is required');

const submissionId = 'sub_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 7);
const now = new Date();
const formattedDate = now.toUTCString();

const emailSubject = `📬 Recruiter Inquiry: ${rawName}${rawCompany ? ' (' + rawCompany + ')' : ''} — ${rawRole}`;

function escapeHtml(str) {
  if (!str) return '';
  return str.replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
}

const emailHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #eae7e1; margin: 0; padding: 24px; color: #1a1a1a; }
    .email-container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #dedede; box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
    .header { background: #5c6470; color: #ffffff; padding: 24px; text-align: left; }
    .header h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: -0.01em; }
    .header p { margin: 6px 0 0 0; font-size: 13px; color: #d0d4dc; }
    .content { padding: 28px 24px; }
    .badge { display: inline-block; background: #f7e0c1; color: #874900; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; padding: 4px 12px; border-radius: 999px; margin-bottom: 16px; }
    .info-table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }
    .info-table td { padding: 10px 12px; font-size: 14px; border-bottom: 1px solid #f0eee8; }
    .info-table td.label { font-weight: 700; color: #5c6470; width: 140px; text-transform: uppercase; font-size: 11px; letter-spacing: 0.04em; }
    .info-table td.val { color: #1a1a1a; }
    .message-box { background: #fdfaf6; border-left: 4px solid #d9381e; padding: 18px; border-radius: 4px; margin-top: 8px; margin-bottom: 24px; }
    .message-box h4 { margin: 0 0 8px 0; font-size: 12px; font-weight: 700; color: #d9381e; text-transform: uppercase; letter-spacing: 0.05em; }
    .message-box p { margin: 0; font-size: 14.5px; line-height: 1.6; white-space: pre-wrap; color: #222; }
    .cta-btn { display: inline-block; background: #d9381e; color: #ffffff !important; text-decoration: none; font-weight: 700; font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; padding: 12px 24px; border-radius: 999px; margin-bottom: 16px; }
    .footer { background: #f8f6f0; padding: 16px 24px; font-size: 11.5px; color: #777; border-top: 1px solid #dedede; }
  </style>
</head>
<body>
  <div class="email-container">
    <div class="header">
      <h1>Géza Horváth — ServiceNow Architect</h1>
      <p>New Recruiter / Opportunity Submission Alert</p>
    </div>
    <div class="content">
      <span class="badge">${escapeHtml(rawRole)}</span>
      <table class="info-table">
        <tr>
          <td class="label">Candidate Name</td>
          <td class="val"><strong>${escapeHtml(rawName)}</strong></td>
        </tr>
        <tr>
          <td class="label">Email Address</td>
          <td class="val"><a href="mailto:${escapeHtml(rawEmail)}">${escapeHtml(rawEmail)}</a></td>
        </tr>
        <tr>
          <td class="label">Organization</td>
          <td class="val">${rawCompany ? escapeHtml(rawCompany) : '<em style="color:#888;">Direct contact (organization unlisted)</em>'}</td>
        </tr>
        <tr>
          <td class="label">Opportunity Scope</td>
          <td class="val">${escapeHtml(rawRole)}</td>
        </tr>
        <tr>
          <td class="label">Phone</td>
          <td class="val">${rawPhone ? escapeHtml(rawPhone) : '<em style="color:#888;">Not provided</em>'}</td>
        </tr>
        <tr>
          <td class="label">Received At</td>
          <td class="val">${escapeHtml(formattedDate)}</td>
        </tr>
        <tr>
          <td class="label">Submission ID</td>
          <td class="val"><code>${escapeHtml(submissionId)}</code></td>
        </tr>
      </table>

      <div class="message-box">
        <h4>Opportunity / Inquiry Details:</h4>
        <p>${escapeHtml(rawMessage)}</p>
      </div>

      <div>
        <a href="mailto:${escapeHtml(rawEmail)}?subject=${encodeURIComponent('Re: ' + rawRole + ' — Géza Horváth')}" class="cta-btn">
          Reply to ${escapeHtml(rawName)} &rarr;
        </a>
      </div>
    </div>
    <div class="footer">
      Persisted to SQLite database (<code>~/resume-ai/contacts.sqlite</code>). Automated via n8n on Mac mini M4.
    </div>
  </div>
</body>
</html>`;

const dbRecord = {
  submissionId: submissionId,
  name: rawName,
  email: rawEmail,
  company: rawCompany,
  roleOrInterest: rawRole,
  phone: rawPhone,
  message: rawMessage,
  source: rawSource
};

const dbBase64 = Buffer.from(JSON.stringify(dbRecord)).toString('base64');

return {
  json: {
    submissionId: submissionId,
    name: rawName,
    email: rawEmail,
    company: rawCompany,
    roleOrInterest: rawRole,
    phone: rawPhone,
    message: rawMessage,
    source: rawSource,
    dbBase64: dbBase64,
    createdAt: now.toISOString(),
    formattedDate: formattedDate,
    emailSubject: emailSubject,
    emailHtml: emailHtml,
    logLine: JSON.stringify({ ...dbRecord, timestamp: now.toISOString() }) + '\n'
  }
};

